import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {randomUUID,createHash} from 'node:crypto';import {atomicJson} from '../execution/ledger.mjs';import {validateUniverse} from '../live-paper/breadth.mjs';import {openCollectorMarketScreen} from '../live-paper/collector-market-screen-v1.mjs';
